/* Function bodies: one part per PRG bank, #included below
 * (single translation unit — see the FullPart note in the
 * recompiler's code_generator.c). */
#include "teyandee_full_bank07.c"
#include "teyandee_full_bank00.c"
#include "teyandee_full_bank01.c"
#include "teyandee_full_bank02.c"
